package chtypes

// fetch_fixtures_test.go — the shared test vectors (docs/guides/fetch.md §9).
//
// tests/fixtures/fetch/ holds miniature releases generated by the core
// repository's tooling: signed/, bad-signature/, tampered-tarball/,
// sums-index-mismatch/, unsigned/, a chtypes.lock that pins signed/, and
// the TEST key under test-key/. expected.json beside them is the
// machine-readable verdict table; this file drives it, so the Go SDK's
// verdicts are the fixtures' verdicts by construction, not by transcription.
//
// The fixtures live outside the Go module (they are the spec's, shared by
// four SDKs), so they are reached by path: $CHTYPES_FETCH_FIXTURES, else
// ../../tests/fixtures/fetch relative to this package. Absent, the test
// SKIPS LOUDLY — the census prints it — and fetch_test.go's self-built
// releases still cover the chain.

import (
	"bytes"
	"context"
	"encoding/json"
	"fmt"
	"os"
	"path/filepath"
	"strconv"
	"strings"
	"testing"

	"github.com/wave-rf/chtypes/go/internal/testhook"
)

type fixtureExpectations struct {
	KeyID       string            `json:"key_id"`
	Lines       map[string]string `json:"lines"`
	Platforms   []string          `json:"platforms"`
	TrustedKeys []string          `json:"trusted_keys"`
	Lock        struct {
		File string `json:"file"`
		Pins string `json:"pins"`
	} `json:"lock"`
	Unpublished struct {
		Code     string `json:"code"`
		Exit     int    `json:"exit"`
		Line     string `json:"line"`
		Patch    string `json:"patch"`
		Platform string `json:"platform"`
	} `json:"unpublished"`
	Verdicts []struct {
		AllowUnsigned bool    `json:"allow_unsigned"`
		Code          *string `json:"code"`
		Exit          int     `json:"exit"`
		Fixture       string  `json:"fixture"`
		TrustedKeys   string  `json:"trusted_keys"` // "test" | "release"
		Why           string  `json:"why"`
	} `json:"verdicts"`
	Builds struct {
		Cases []struct {
			Platform          string `json:"platform"`
			Line              string `json:"line"`
			ClickHouseVersion string `json:"clickhouse_version"`
			Install           struct {
				File   string `json:"file"`
				SHA256 string `json:"sha256"`
				Build  int    `json:"build"`
			} `json:"install"`
			Superseded struct {
				File   string `json:"file"`
				SHA256 string `json:"sha256"`
				Build  int    `json:"build"`
			} `json:"superseded"`
		} `json:"cases"`
	} `json:"builds"`
	Revisions struct {
		Fixture             string `json:"fixture"`
		LowRevision         int    `json:"low_revision"`
		HighRevision        int    `json:"high_revision"`
		DiscriminatingLines []struct {
			Revision int    `json:"revision"`
			Line     string `json:"line"`
		} `json:"discriminating_lines"`
		Cases []revisionCase `json:"cases"`
	} `json:"revisions"`
}

// revisionPick is one row of two-revisions/, as expected.json names it.
type revisionPick struct {
	File        string `json:"file"`
	SHA256      string `json:"sha256"`
	Build       int    `json:"build"`
	ABIRevision int    `json:"abi_revision"`
}

// revisionCase is one (platform, line) of expected.json's revisions.cases:
// the row fetch must install at the low and at the high revision, and the row
// an unfiltered resolve would take.
type revisionCase struct {
	Platform   string       `json:"platform"`
	Line       string       `json:"line"`
	AtLow      revisionPick `json:"at_low_revision"`
	AtHigh     revisionPick `json:"at_high_revision"`
	Unfiltered revisionPick `json:"unfiltered"`
}

// fixtureDir locates tests/fixtures/fetch or skips loudly.
func fixtureDir(t *testing.T) (string, *fixtureExpectations) {
	t.Helper()
	dir := os.Getenv("CHTYPES_FETCH_FIXTURES")
	if dir == "" {
		dir = filepath.Join("..", "..", "tests", "fixtures", "fetch")
	}
	abs, err := filepath.Abs(dir)
	if err != nil {
		t.Fatal(err)
	}
	b, err := os.ReadFile(filepath.Join(abs, "expected.json"))
	if err != nil {
		t.Skipf("shared fetch fixtures not found: %v (set CHTYPES_FETCH_FIXTURES to tests/fixtures/fetch)", err)
	}
	var exp fixtureExpectations
	if err := json.Unmarshal(b, &exp); err != nil {
		t.Fatalf("expected.json: %v", err)
	}
	if len(exp.Verdicts) == 0 || len(exp.Platforms) == 0 || len(exp.Lines) == 0 || len(exp.TrustedKeys) == 0 {
		t.Fatalf("expected.json is missing verdicts/platforms/lines/keys: %+v", exp)
	}
	useFixtureRevision(t, abs)
	return abs, &exp
}

// useFixtureRevision points fetch's row selection at the ABI revision the
// fixture releases under dir carry, for the rest of the test. Fetch installs
// only rows at the binding's own revision (docs/guides/fetch.md §2), and the
// fixtures are generated at whatever revision the artifact producer was at —
// so the suite reads the revision they declare (testhook.FixturesABIRevision:
// expected.json's fixtures_abi_revision, which fails when it is missing)
// instead of assuming it equals ABIRevision, and never types it.
func useFixtureRevision(t *testing.T, dir string) int {
	t.Helper()
	rev, err := testhook.FixturesABIRevision(dir)
	if err != nil {
		t.Fatalf("fetch fixtures: %v", err)
	}
	prev := testhook.FetchABIRevision
	testhook.FetchABIRevision = rev
	t.Cleanup(func() { testhook.FetchABIRevision = prev })
	return rev
}

// TestFetchFixturesAreFetchedAtTheirOwnRevision proves the override above is
// wired to the declared revision: the fetcher selects at the fixtures' revision, and one
// revision past it the same release refuses UNPUBLISHED, naming both — the
// fixtures have nothing at any other revision.
func TestFetchFixturesAreFetchedAtTheirOwnRevision(t *testing.T) {
	dir, exp := fixtureDir(t)
	rev, err := testhook.FixturesABIRevision(dir)
	if err != nil {
		t.Fatal(err)
	}
	if got := fetchABIRevision(); got != rev {
		t.Fatalf("fetch selects at ABI revision %d, the fixtures carry %d", got, rev)
	}
	isolateEnv(t)
	t.Setenv(envTrustedKeys, strings.Join(exp.TrustedKeys, ","))
	src := "file://" + filepath.Join(dir, "signed")
	testhook.FetchABIRevision = rev + 1
	dest := filepath.Join(t.TempDir(), "reg")
	_, err = Ensure(context.Background(), "25.8", FetchOptions{URL: src, Dest: dest, Platform: exp.Platforms[0]})
	ae := wantCode(t, err, CodeArtifactUnpublished)
	for _, want := range []string{"ABI revision " + strconv.Itoa(rev+1), "only at ABI revision " + strconv.Itoa(rev)} {
		if !strings.Contains(ae.Msg, want) {
			t.Fatalf("message does not name %q: %s", want, ae.Msg)
		}
	}
	noArtifactDirs(t, dest)
}

func TestFetchFixturesTestKeyMatchesExpectedKeyID(t *testing.T) {
	dir, exp := fixtureDir(t)
	pubHex, err := os.ReadFile(filepath.Join(dir, "test-key", "public.hex"))
	if err != nil {
		t.Fatal(err)
	}
	if got := strings.TrimSpace(string(pubHex)); got != exp.TrustedKeys[0] {
		t.Fatalf("test-key/public.hex %s != expected.json trusted_keys %s", got, exp.TrustedKeys[0])
	}
	keys, err := ParseTrustedKeys(exp.TrustedKeys[0])
	if err != nil {
		t.Fatal(err)
	}
	if KeyID(keys[0]) != exp.KeyID {
		t.Fatalf("KeyID(test key) = %s, want %s", KeyID(keys[0]), exp.KeyID)
	}
	if exp.KeyID == ReleaseKeyID || exp.TrustedKeys[0] == ReleasePublicKeyHex {
		t.Fatal("the fixtures are signed with the release key — they must never be")
	}
}

func TestFetchFixturesEveryVerdictMatchesExpected(t *testing.T) {
	dir, exp := fixtureDir(t)
	for _, v := range exp.Verdicts {
		v := v
		name := v.Fixture + "/" + v.TrustedKeys
		if v.AllowUnsigned {
			name += "/allow-unsigned"
		}
		t.Run(name, func(t *testing.T) {
			isolateEnv(t)
			if v.TrustedKeys == "test" {
				t.Setenv(envTrustedKeys, strings.Join(exp.TrustedKeys, ","))
			}
			if v.AllowUnsigned {
				t.Setenv(envAllowUnsign, "1")
			}
			src := "file://" + filepath.Join(dir, v.Fixture)
			// Every published (platform, line) row must give the same verdict.
			for _, platform := range exp.Platforms {
				for line, patch := range exp.Lines {
					dest := filepath.Join(t.TempDir(), platform)
					var progress bytes.Buffer
					inst, err := Ensure(context.Background(), line, FetchOptions{URL: src, Dest: dest, Platform: platform, Progress: &progress})
					if v.Code == nil {
						if err != nil {
							t.Fatalf("%s %s: %v — %s\n%s", platform, line, err, v.Why, progress.String())
						}
						if inst.Version != patch || inst.Line != line || inst.Platform != platform || inst.Dir != filepath.Join(dest, line) {
							t.Fatalf("%s %s: installed %+v, want %s", platform, line, inst, patch)
						}
						vr, err := VerifyInstalled(dest)
						if err != nil || len(vr) != 1 || !vr[0].OK {
							t.Fatalf("%s %s: verify %+v %v", platform, line, vr, err)
						}
						if v.AllowUnsigned {
							if inst.SignedBy != "" || !strings.Contains(progress.String(), "WARNING") || !strings.Contains(progress.String(), filepath.Join(dir, v.Fixture)) {
								t.Fatalf("%s %s: no loud warning naming the source:\n%s", platform, line, progress.String())
							}
						} else if inst.SignedBy != exp.KeyID {
							t.Fatalf("%s %s: SignedBy %s, want %s", platform, line, inst.SignedBy, exp.KeyID)
						}
						if ExitCode(err) != v.Exit {
							t.Fatalf("exit %d, want %d", ExitCode(err), v.Exit)
						}
						continue
					}
					ae := wantCode(t, err, ErrorCode(*v.Code))
					if ExitCode(err) != v.Exit {
						t.Fatalf("%s %s: exit %d, want %d (%s)", platform, line, ExitCode(err), v.Exit, v.Why)
					}
					if ae.Platform != platform || ae.Line != line {
						t.Fatalf("%s %s: error names %s %s", platform, line, ae.Platform, ae.Line)
					}
					noArtifactDirs(t, dest)
					if strings.Contains(progress.String(), "installed and verified") {
						t.Fatalf("%s %s: claimed an install:\n%s", platform, line, progress.String())
					}
				}
			}
		})
	}
}

func TestFetchFixturesUnpublishedPlatformLineAndPatchAreRefused(t *testing.T) {
	dir, exp := fixtureDir(t)
	isolateEnv(t)
	t.Setenv(envTrustedKeys, strings.Join(exp.TrustedKeys, ","))
	src := "file://" + filepath.Join(dir, "signed")
	u := exp.Unpublished
	code := ErrorCode(u.Code)
	dest := filepath.Join(t.TempDir(), "reg")
	// A platform the fixtures do not publish.
	_, err := Ensure(context.Background(), "25.8", FetchOptions{URL: src, Dest: dest, Platform: u.Platform})
	if ae := wantCode(t, err, code); ExitCode(err) != u.Exit || ae.Platform != u.Platform {
		t.Fatalf("%+v exit %d", ae, ExitCode(err))
	}
	// A line, and an exact patch, they do not publish — on a platform they do.
	for _, spelling := range []string{u.Line, u.Patch} {
		_, err := Ensure(context.Background(), spelling, FetchOptions{URL: src, Dest: dest, Platform: exp.Platforms[0]})
		if ae := wantCode(t, err, code); ExitCode(err) != u.Exit || ae.Line != spelling {
			t.Fatalf("%s: %+v exit %d", spelling, ae, ExitCode(err))
		}
	}
	noArtifactDirs(t, dest)
	// --all installs exactly the published lines for a platform.
	all, err := FetchAll(context.Background(), FetchOptions{URL: src, Dest: dest, Platform: exp.Platforms[0]})
	if err != nil || len(all) != len(exp.Lines) {
		t.Fatalf("FetchAll = %d, %v", len(all), err)
	}
	for _, inst := range all {
		if exp.Lines[inst.Line] != inst.Version {
			t.Fatalf("FetchAll installed %s %s", inst.Line, inst.Version)
		}
	}
}

func TestFetchFixturesLockRecordsAndFrozenRefusesDrift(t *testing.T) {
	dir, exp := fixtureDir(t)
	rev, err := testhook.FixturesABIRevision(dir)
	if err != nil {
		t.Fatal(err)
	}
	isolateEnv(t)
	t.Setenv(envTrustedKeys, strings.Join(exp.TrustedKeys, ","))
	lock := filepath.Join(dir, exp.Lock.File)
	src := "file://" + filepath.Join(dir, exp.Lock.Pins)
	l, err := ReadLockFile(lock)
	if err != nil || l.Schema != LockSchema {
		t.Fatalf("lock: %+v %v", l, err)
	}
	// The committed fixture lock predates abi_revision (docs/guides/fetch.md
	// §5): its entries carry none, and --frozen against it still installs —
	// the no-abi_revision path is the old behavior, unchanged.
	for _, e := range l.Artifacts {
		if e.ABIRevision != nil {
			t.Fatalf("the committed fixture lock should carry no abi_revision: %+v", e)
		}
	}
	// --frozen with the shared lock installs every pinned row of signed/.
	for _, platform := range exp.Platforms {
		for line := range exp.Lines {
			key := LockKey(platform, line)
			if _, ok := l.Artifacts[key]; !ok {
				t.Fatalf("lock does not pin %s", key)
			}
			dest := filepath.Join(t.TempDir(), platform)
			inst, err := Ensure(context.Background(), line, FetchOptions{URL: src, Dest: dest, Platform: platform, LockFile: lock, Frozen: true})
			if err != nil {
				t.Fatalf("frozen %s: %v", key, err)
			}
			if e := l.Artifacts[key]; e.File != inst.File || e.SHA256 != inst.SHA256 {
				t.Fatalf("%s: installed %s %s, lock says %s %s", key, inst.File, inst.SHA256, e.File, e.SHA256)
			}
		}
	}
	// The lock this SDK writes from a fresh fetch pins the shared lock's own
	// file and sha256, entry for entry, and now also the fixtures' own ABI
	// revision — the one new thing a fresh fetch records (docs/guides/fetch.md §5).
	mine := filepath.Join(t.TempDir(), "chtypes.lock")
	for _, platform := range exp.Platforms {
		for line := range exp.Lines {
			if _, err := Ensure(context.Background(), line, FetchOptions{URL: src, Dest: filepath.Join(t.TempDir(), platform), Platform: platform, LockFile: mine}); err != nil {
				t.Fatal(err)
			}
		}
	}
	written, err := ReadLockFile(mine)
	if err != nil {
		t.Fatal(err)
	}
	if len(written.Artifacts) != len(l.Artifacts) {
		t.Fatalf("wrote %d entries, the shared lock has %d", len(written.Artifacts), len(l.Artifacts))
	}
	for k, e := range l.Artifacts {
		w := written.Artifacts[k]
		if w.File != e.File || w.SHA256 != e.SHA256 {
			t.Fatalf("%s: wrote %+v, shared %+v", k, w, e)
		}
		if w.ABIRevision == nil || *w.ABIRevision != rev {
			t.Fatalf("%s: wrote abi_revision %v, want %d", k, w.ABIRevision, rev)
		}
	}
	// A copy whose sha256 was changed is refused with CHTYPES_ARTIFACT_PINNED.
	platform, line := exp.Platforms[0], "25.8"
	key := LockKey(platform, line)
	drifted := NewLockFile()
	for k, e := range l.Artifacts {
		drifted.Artifacts[k] = e
	}
	e := drifted.Artifacts[key]
	e.SHA256 = strings.Repeat("0", 64)
	drifted.Artifacts[key] = e
	driftedPath := filepath.Join(t.TempDir(), "drifted.lock")
	if err := drifted.Write(driftedPath); err != nil {
		t.Fatal(err)
	}
	dest := filepath.Join(t.TempDir(), "reg")
	_, err = Ensure(context.Background(), line, FetchOptions{URL: src, Dest: dest, Platform: platform, LockFile: driftedPath, Frozen: true})
	if wantCode(t, err, CodeArtifactPinned); ExitCode(err) != 1 {
		t.Fatalf("exit %d", ExitCode(err))
	}
	noArtifactDirs(t, dest)
}

// TestFetchFixturesRebuildInstallsTheHighestBuild walks expected.json's builds.cases
// against the two-builds/ fixture, where one ClickHouse version is published
// twice — the shape a rebuild leaves behind, and the shape the live release has
// carried since builds existed.
//
// Resolving a line is therefore not a question about the ClickHouse version
// alone: among rows of the newest version, the highest build wins. Until this,
// nothing in any of the four suites covered that; the rule was pinned only by
// unit tests of the comparator itself.
//
// The proof is the installed library's own bytes. Both rows carry the same
// clickhouse_version, so a manifest check cannot separate them — their
// library_sha256 differs, and the installed file is hashed in place. An
// implementation that took the first matching row, or the older build, fails
// here instead of passing quietly.
func TestFetchFixturesRebuildInstallsTheHighestBuild(t *testing.T) {
	dir, exp := fixtureDir(t)
	if len(exp.Builds.Cases) == 0 {
		t.Skip("expected.json carries no builds.cases — regenerate the fixtures from the release pipeline")
	}
	var index struct {
		Artifacts []ReleaseArtifact `json:"artifacts"`
	}
	blob, err := os.ReadFile(filepath.Join(dir, "two-builds", "index.json"))
	if err != nil {
		t.Fatalf("two-builds/index.json: %v", err)
	}
	if err := json.Unmarshal(blob, &index); err != nil {
		t.Fatalf("two-builds/index.json: %v", err)
	}
	rowFor := func(file string) *ReleaseArtifact {
		for i := range index.Artifacts {
			if index.Artifacts[i].File == file {
				return &index.Artifacts[i]
			}
		}
		return nil
	}

	for _, c := range exp.Builds.Cases {
		c := c
		t.Run(c.Platform+"/"+c.Line, func(t *testing.T) {
			isolateEnv(t)
			t.Setenv(envTrustedKeys, strings.Join(exp.TrustedKeys, ","))
			want, other := rowFor(c.Install.File), rowFor(c.Superseded.File)
			if want == nil || other == nil {
				t.Fatalf("two-builds/index.json has no row for %s or %s", c.Install.File, c.Superseded.File)
			}
			if want.BuildNumber() <= other.BuildNumber() {
				t.Fatalf("the fixture's own case is upside down: install b%d, superseded b%d", want.BuildNumber(), other.BuildNumber())
			}
			if want.ClickHouseVersion != other.ClickHouseVersion {
				t.Fatalf("the two rows are different versions, so this proves nothing about builds: %s vs %s", want.ClickHouseVersion, other.ClickHouseVersion)
			}

			dest := t.TempDir()
			inst, err := Ensure(context.Background(), c.Line, FetchOptions{
				URL: "file://" + filepath.Join(dir, "two-builds"), Dest: dest, Platform: c.Platform,
			})
			if err != nil {
				t.Fatalf("%s %s: %v", c.Platform, c.Line, err)
			}
			// The library on disk must be the HIGHER build's, byte for byte.
			lib := filepath.Join(inst.Dir, inst.Library)
			got, err := fileSHA256(lib)
			if err != nil {
				t.Fatalf("hash %s: %v", lib, err)
			}
			if got != want.LibrarySHA256 {
				t.Fatalf("%s %s: installed library hashes %s, want build %d (%s)", c.Platform, c.Line, got, want.BuildNumber(), want.LibrarySHA256)
			}
			if got == other.LibrarySHA256 {
				t.Fatalf("%s %s: the SUPERSEDED build %d is what landed", c.Platform, c.Line, other.BuildNumber())
			}
		})
	}
}

// twoRevisions loads expected.json's revisions block and the two-revisions/
// fixture's own index rows by file, failing when either is absent.
func twoRevisions(t *testing.T) (string, *fixtureExpectations, map[string]ReleaseArtifact) {
	t.Helper()
	dir, exp := fixtureDir(t)
	r := exp.Revisions
	if r.Fixture == "" || len(r.Cases) == 0 || len(r.DiscriminatingLines) == 0 || r.HighRevision <= r.LowRevision {
		t.Fatalf("expected.json carries no usable revisions block (%+v) — regenerate the fixtures", r)
	}
	var index struct {
		Artifacts []ReleaseArtifact `json:"artifacts"`
	}
	blob, err := os.ReadFile(filepath.Join(dir, r.Fixture, "index.json"))
	if err != nil {
		t.Fatalf("%s/index.json: %v", r.Fixture, err)
	}
	if err := json.Unmarshal(blob, &index); err != nil {
		t.Fatalf("%s/index.json: %v", r.Fixture, err)
	}
	byFile := map[string]ReleaseArtifact{}
	for _, a := range index.Artifacts {
		byFile[a.File] = a
	}
	isolateEnv(t)
	t.Setenv(envTrustedKeys, strings.Join(exp.TrustedKeys, ","))
	return dir, exp, byFile
}

// fetchAtRevision fetches one line of two-revisions/ with fetch selecting at
// revision rev, and checks that what landed is want: the file, its sha256,
// the row's own build and abi_revision, and the installed library's bytes.
func fetchAtRevision(t *testing.T, dir string, exp *fixtureExpectations, byFile map[string]ReleaseArtifact,
	c revisionCase, rev int, want revisionPick) {
	t.Helper()
	testhook.FetchABIRevision = rev
	inst, err := Ensure(context.Background(), c.Line, FetchOptions{
		URL: "file://" + filepath.Join(dir, exp.Revisions.Fixture), Dest: t.TempDir(), Platform: c.Platform,
	})
	if err != nil {
		t.Fatalf("%s %s at ABI revision %d: %v", c.Platform, c.Line, rev, err)
	}
	if inst.File != want.File || inst.SHA256 != want.SHA256 {
		t.Fatalf("%s %s at ABI revision %d installed %s (%s), want %s (%s)", c.Platform, c.Line, rev, inst.File, inst.SHA256, want.File, want.SHA256)
	}
	row, ok := byFile[want.File]
	if !ok || row.BuildNumber() != want.Build || !row.atRevision(want.ABIRevision) || want.ABIRevision != rev {
		t.Fatalf("%s: index row %+v disagrees with expected.json's build %d / abi_revision %d at revision %d", want.File, row, want.Build, want.ABIRevision, rev)
	}
	got, err := fileSHA256(filepath.Join(inst.Dir, inst.Library))
	if err != nil || got != row.LibrarySHA256 {
		t.Fatalf("%s: installed library hashes %s (%v), the row says %s", want.File, got, err, row.LibrarySHA256)
	}
}

// TestFetchFixturesTwoRevisionsPickTheRowAtEachRevision drives every case of
// expected.json's revisions against two-revisions/: at the low revision the
// pick is at_low_revision, at the high revision it is at_high_revision — the
// file, sha256, build and revision all read from expected.json.
func TestFetchFixturesTwoRevisionsPickTheRowAtEachRevision(t *testing.T) {
	dir, exp, byFile := twoRevisions(t)
	r := exp.Revisions
	for _, c := range r.Cases {
		for _, at := range []struct {
			rev  int
			want revisionPick
		}{{r.LowRevision, c.AtLow}, {r.HighRevision, c.AtHigh}} {
			t.Run(fmt.Sprintf("%s/%s/abi%d", c.Platform, c.Line, at.rev), func(t *testing.T) {
				fetchAtRevision(t, dir, exp, byFile, c, at.rev, at.want)
			})
		}
	}
}

// TestFetchFixturesTwoRevisionsFilterChangesTheAnswer asserts the
// discriminating lines expected.json names: at that revision, on that line,
// the pick DIFFERS from the unfiltered one — so the filter decided it, not
// two rules that happened to agree.
func TestFetchFixturesTwoRevisionsFilterChangesTheAnswer(t *testing.T) {
	dir, exp, byFile := twoRevisions(t)
	r := exp.Revisions
	for _, d := range r.DiscriminatingLines {
		t.Run(fmt.Sprintf("abi%d/%s", d.Revision, d.Line), func(t *testing.T) {
			checked := 0
			for _, c := range r.Cases {
				if c.Line != d.Line {
					continue
				}
				var want revisionPick
				switch d.Revision {
				case r.LowRevision:
					want = c.AtLow
				case r.HighRevision:
					want = c.AtHigh
				default:
					t.Fatalf("discriminating revision %d is neither low (%d) nor high (%d)", d.Revision, r.LowRevision, r.HighRevision)
				}
				if want.File == c.Unfiltered.File {
					t.Fatalf("%s %s: expected.json's pick at ABI revision %d is the unfiltered one — this line does not discriminate", c.Platform, c.Line, d.Revision)
				}
				fetchAtRevision(t, dir, exp, byFile, c, d.Revision, want)
				checked++
			}
			if checked == 0 {
				t.Fatalf("no case for discriminating line %s", d.Line)
			}
		})
	}
}

// TestFetchFixturesTwoRevisionsOnePastTheHighRevisionIsUnpublished is the
// negative control: the release serves nothing at high_revision + 1.
func TestFetchFixturesTwoRevisionsOnePastTheHighRevisionIsUnpublished(t *testing.T) {
	dir, exp, _ := twoRevisions(t)
	r := exp.Revisions
	c := r.Cases[0]
	testhook.FetchABIRevision = r.HighRevision + 1
	dest := filepath.Join(t.TempDir(), "reg")
	_, err := Ensure(context.Background(), c.Line, FetchOptions{
		URL: "file://" + filepath.Join(dir, r.Fixture), Dest: dest, Platform: c.Platform,
	})
	ae := wantCode(t, err, CodeArtifactUnpublished)
	if !strings.Contains(ae.Msg, fmt.Sprintf("ABI revision %d (this SDK's)", r.HighRevision+1)) {
		t.Fatalf("message: %s", ae.Msg)
	}
	noArtifactDirs(t, dest)
}
